"""Expression evaluation helpers for minisql.

AST nodes are dictionaries (see ``eval_expr``); keeping this module independent
of the parser makes the execution semantics easy to reuse for rows and groups.
"""
import math
import re
from decimal import Decimal, ROUND_HALF_UP


AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
SCALARS = {"LOWER", "UPPER", "LENGTH", "ABS", "ROUND", "COALESCE"}


def _error(message):
    # Imported lazily because __init__ imports the execution modules.
    from . import QueryError
    raise QueryError(message)


def truth(value):
    """SQL truth conversion, rejecting values that are not booleans."""
    if value is None or isinstance(value, bool):
        return value
    _error("logical operators require booleans")


def _compare(a, b, op):
    if a is None or b is None:
        return None
    if isinstance(a, bool) or isinstance(b, bool):
        if not (isinstance(a, bool) and isinstance(b, bool)):
            _error("cannot compare boolean and non-boolean values")
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    else:
        _error("incompatible values in comparison")
    try:
        return {"=": lambda: a == b, "!=": lambda: a != b,
                "<>": lambda: a != b, "<": lambda: a < b,
                "<=": lambda: a <= b, ">": lambda: a > b,
                ">=": lambda: a >= b}[op]()
    except KeyError:
        _error("unknown comparison operator: " + str(op))


def _round(value, places=None):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        _error("ROUND requires a number")
    places = 0 if places is None else places
    if isinstance(places, bool) or not isinstance(places, int):
        _error("ROUND precision must be an integer")
    # Decimal(str(...)) avoids binary tie surprises and ROUND_HALF_UP is away
    # from zero after sign handling via quantize.
    quantum = Decimal(1).scaleb(-places)
    result = Decimal(str(value)).copy_abs().quantize(quantum, rounding=ROUND_HALF_UP)
    if value < 0:
        result = -result
    if places == 0:
        return int(result)
    return float(result)


def _aggregate(name, args, rows, headers):
    name = name.upper()
    if name == "COUNT" and len(args) == 1 and args[0] == "*":
        return len(rows)
    if len(args) != 1 or args[0] == "*":
        _error(name + " requires exactly one expression")
    vals = [eval_expr(args[0], row, headers) for row in rows]
    vals = [v for v in vals if v is not None]
    if name == "COUNT":
        return len(vals)
    if not vals:
        return None
    if name in ("SUM", "AVG"):
        for v in vals:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                _error(name + " requires numeric values")
        return sum(vals) if name == "SUM" else float(sum(vals) / len(vals))
    for v in vals[1:]:
        _compare(vals[0], v, "=")
    return min(vals) if name == "MIN" else max(vals)


def eval_expr(node, row=None, headers=None, group=None):
    """Evaluate a dictionary AST node against a row or aggregate group.

    Column lookup is case-insensitive. ``row`` may be a mapping or a sequence
    paired with ``headers``. For aggregate evaluation, ``group`` is a sequence
    of input rows; it defaults to a singleton containing ``row``.
    """
    headers = headers or []
    if not isinstance(node, dict):
        # Convenient support for literal values and parser tuple nodes.
        if isinstance(node, tuple) and node:
            node = dict(zip(("type", "op", "left", "right"), node))
        else:
            return node
    typ = node.get("type")
    if typ in ("literal", "value"):
        return node.get("value")
    if typ in ("column", "name", "identifier"):
        key = node.get("name", node.get("value"))
        if isinstance(row, dict):
            lookup = {str(k).casefold(): v for k, v in row.items()}
            if str(key).casefold() not in lookup:
                _error("unknown column: " + str(key))
            return lookup[str(key).casefold()]
        for i, h in enumerate(headers):
            if str(h).casefold() == str(key).casefold():
                try:
                    return row[i]
                except (IndexError, TypeError):
                    break
        _error("unknown column: " + str(key))
    if typ == "call":
        name = str(node["name"]).upper()
        args = node.get("args", [])
        if name in AGGREGATES:
            if group is None:
                group = [] if row is None else [row]
            return _aggregate(name, args, group, headers)
        if name not in SCALARS:
            _error("unknown function: " + name)
        if name == "COALESCE":
            if not args: _error("COALESCE requires at least one argument")
            for arg in args:
                value = eval_expr(arg, row, headers, group)
                if value is not None: return value
            return None
        expected = {"LOWER": (1,), "UPPER": (1,), "LENGTH": (1,), "ABS": (1,), "ROUND": (1, 2)}[name]
        if len(args) not in expected: _error("wrong number of arguments to " + name)
        values = [eval_expr(a, row, headers, group) for a in args]
        if any(v is None for v in values): return None
        x = values[0]
        if name in ("LOWER", "UPPER"):
            if not isinstance(x, str): _error(name + " requires a string")
            return x.lower() if name == "LOWER" else x.upper()
        if name == "LENGTH":
            if not isinstance(x, str): _error("LENGTH requires a string")
            return len(x)
        if name == "ABS":
            if isinstance(x, bool) or not isinstance(x, (int, float)): _error("ABS requires a number")
            return abs(x)
        return _round(x, values[1] if len(values) == 2 else None)
    if typ == "isnull":
        result = eval_expr(node["expr"], row, headers, group) is None
        return not result if node.get("negated") else result
    if typ == "in":
        x = eval_expr(node["expr"], row, headers, group)
        vals = [eval_expr(a, row, headers, group) for a in node.get("items", [])]
        if x is None: result = None
        elif any(v is not None and _compare(x, v, "=") for v in vals): result = True
        elif any(v is None for v in vals): result = None
        else: result = False
        return (not result if result is not None else None) if node.get("negated") else result
    if typ == "between":
        x = eval_expr(node["expr"], row, headers, group)
        lo = eval_expr(node["low"], row, headers, group)
        hi = eval_expr(node["high"], row, headers, group)
        result = None if x is None or lo is None or hi is None else (_compare(lo, x, "<=") and _compare(x, hi, "<="))
        return (not result if result is not None else None) if node.get("negated") else result
    if typ == "unary":
        op = str(node["op"]).upper(); v = eval_expr(node["expr"], row, headers, group)
        if op == "NOT":
            v = truth(v); return None if v is None else not v
        if v is None: return None
        if op == "-":
            if isinstance(v, bool) or not isinstance(v, (int, float)): _error("unary - requires a number")
            return -v
    if typ == "binary":
        op = str(node["op"]).upper(); a = eval_expr(node["left"], row, headers, group)
        if op == "AND":
            a = truth(a)
            if a is False: return False
            b = truth(eval_expr(node["right"], row, headers, group))
            return False if b is False else (None if a is None or b is None else True)
        if op == "OR":
            a = truth(a)
            if a is True: return True
            b = truth(eval_expr(node["right"], row, headers, group))
            return True if b is True else (None if a is None or b is None else False)
        b = eval_expr(node["right"], row, headers, group)
        if op in ("=", "!=", "<>", "<", "<=", ">", ">="): return _compare(a, b, op)
        if a is None or b is None: return None
        if op == "||": return str(a) + str(b)
        if op in ("+", "-", "*", "/"):
            if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in (a, b)):
                _error("arithmetic requires numeric values")
            if op == "/": return None if b == 0 else a / b
            return {"+": lambda: a+b, "-": lambda: a-b, "*": lambda: a*b}[op]()
    _error("invalid expression")


def contains_aggregate(node):
    if not isinstance(node, dict): return False
    if node.get("type") == "call" and str(node.get("name", "")).upper() in AGGREGATES: return True
    return any(contains_aggregate(v) for v in node.values()) if isinstance(node, dict) else False


def validate_aggregates(node, inside=False, where=False):
    """Raise QueryError for nested aggregates or any aggregate in WHERE."""
    if not isinstance(node, dict): return
    isagg = node.get("type") == "call" and str(node.get("name", "")).upper() in AGGREGATES
    if isagg and where: _error("aggregates are not allowed in WHERE")
    if isagg and inside: _error("aggregate functions cannot be nested")
    for value in node.values():
        if isinstance(value, dict): validate_aggregates(value, inside or isagg, where)
        elif isinstance(value, list):
            for child in value:
                if isinstance(child, dict): validate_aggregates(child, inside or isagg, where)

